{"code":"const meyveler = ["alma", "armud", "banan"];

console.log(meyveler[0]); // "alma" - sayma 0-dan başlayır!
console.log(meyveler[1]); // "armud"
console.log(meyveler.length); // 3 - massivdə neçə element var","language":"javascript","caption":"Array nümunəsi"}

{"code":"const isci = {
  ad: "Nicat",
  yas: 28,
  vezife: "SDET",
  isAktiv: true
};

console.log(isci.ad);      // "Nicat"
console.log(isci.vezife);  // "SDET"","language":"javascript","caption":"Object nümunəsi"}

{"emoji":"📦","title":"Array vs Object — Fərq nədir?","body":"Array — sıralı siyahı, elementlərə nömrə ilə müraciət edirsən (meyveler[0]).
Object — adlandırılmış məlumat toplusu, elementlərə ad ilə müraciət edirsən (isci.ad).

Sadə qayda: sıralı, oxşar tipli siyahı üçün Array; müxtəlif xüsusiyyətləri olan bir "şey"i təsvir etmək üçün Object istifadə et.","color":"purple"}

{"code":"const a = 10;
const b = 3;

console.log(a + b); // 13
console.log(a - b); // 7
console.log(a * b); // 30
console.log(a / b); // 3.333...
console.log(a % b); // 1 — 10-u 3-ə böləndə qalan","language":"javascript","caption":"Riyazi operatorlar nümunəsi"}

{"code":"const yas = 20;

if (yas >= 18) {
  console.log("Sən yetkinsən.");
} else {
  console.log("Sən hələ yetkin deyilsən.");
}","language":"javascript","caption":"Sadə if / else nümunəsi"}

{"code":"const qiymet = 85;

if (qiymet >= 90) {
  console.log("Əla");
} else if (qiymet >= 70) {
  console.log("Yaxşı");
} else if (qiymet >= 50) {
  console.log("Kafi");
} else {
  console.log("Qeyri-kafi");
}
// Nəticə: "Yaxşı" çap olunacaq, çünki 85 >= 70 şərti doğrudur","language":"javascript","caption":"if / else if / else nümunəsi"}

{"code":"const gun = "Bazar ertəsi";

switch (gun) {
  case "Bazar ertəsi":
    console.log("Həftənin ilk günüdür");
    break;
  case "Cümə":
    console.log("İş həftəsi bitir");
    break;
  case "Şənbə":
  case "Bazar":
    console.log("Həftəsonudur");
    break;
  default:
    console.log("Adi iş günüdür");
}
// Nəticə: "Həftənin ilk günüdür"","language":"javascript","caption":"switch operatoru nümunəsi"}

{"code":"const yas = 25;
const biletVar = true;

// && - hər ikisi doğru olmalıdır
if (yas >= 18 && biletVar) {
  console.log("Konsertə buraxılırsan");
}

// || - biri doğru olsa kifayətdir
const heftesonu = false;
const tetil = true;
if (heftesonu || tetil) {
  console.log("Bu gün istirahət edə bilərsən");
}

// ! - əksini yoxlayır
const isLoggedIn = false;
if (!isLoggedIn) {
  console.log("Sən daxil olmamısan");
}","language":"javascript","caption":"Məntiqi operatorlar nümunəsi"}

{"code":"for (let i = 1; i <= 5; i++) {
  console.log(i);
}
// Nəticə: 1, 2, 3, 4, 5 (hər biri ayrı sətirdə çap olunur)","language":"javascript","caption":"Sadə for dövrü"}

{"code":"let i = 1;

while (i <= 5) {
  console.log(i);
  i++; // unutmaq olmaz! yoxsa dövr heç vaxt bitməz
}
// Nəticə: 1, 2, 3, 4, 5","language":"javascript","caption":"while dövrü nümunəsi"}

{"code":"let sayi = 10;

do {
  console.log(sayi); // əvvəlcə bu icra olunur
  sayi++;
} while (sayi <= 5); // sonra şərt yoxlanılır

// Nəticə: 10 (bir dəfə çap olunur, çünki do-while əvvəlcə icra edir, sonra yoxlayır)","language":"javascript","caption":"do-while nümunəsi"}

{"emoji":"💡","title":"while vs do-while fərqi","body":"while — əvvəlcə şərti yoxlayır, doğrudursa icra edir (heç icra olunmaya bilər).
do-while — əvvəlcə icra edir, sonra şərti yoxlayır (həmişə ən azı 1 dəfə icra olunur).

do-while praktikada az istifadə olunur, amma anlayışını bilmək faydalıdır.","color":"yellow"}

{"code":"// for...of — Array-in İÇİNDƏKİ DƏYƏRLƏRİ gəzir
const meyveler = ["alma", "armud", "banan"];

for (const meyve of meyveler) {
  console.log(meyve);
}
// Nəticə: "alma", "armud", "banan"","language":"javascript","caption":"for...of nümunəsi (Array üçün)"}

{"code":"// for...in — Object-in AÇARLARINI (key) gəzir
const isci = { ad: "Nicat", yas: 28, vezife: "SDET" };

for (const acar in isci) {
  console.log(acar + ": " + isci[acar]);
}
// Nəticə: "ad: Nicat", "yas: 28", "vezife: SDET"","language":"javascript","caption":"for...in nümunəsi (Object üçün)"}

{"code":"const meyveler = ["alma", "armud", "banan"];

meyveler.forEach(function (meyve) {
  console.log(meyve);
});
// Nəticə: "alma", "armud", "banan"","language":"javascript","caption":"forEach nümunəsi"}

{"code":"const ededler = [1, 2, 3, 4];

const ikiqat = ededler.map(function (eded) {
  return eded * 2;
});

console.log(ikiqat); // [2, 4, 6, 8]
console.log(ededler); // [1, 2, 3, 4] — orijinal array dəyişmir!","language":"javascript","caption":"map nümunəsi"}

{"code":"const ededler = [1, 2, 3, 4, 5, 6];

const cutEdedler = ededler.filter(function (eded) {
  return eded % 2 === 0;
});

console.log(cutEdedler); // [2, 4, 6]","language":"javascript","caption":"filter nümunəsi"}
